window.renderTopbar = renderTopbar;

window.toggleTopbarMoreMenu = function(e) {
  if (e) {
    if (typeof e.preventDefault === 'function') e.preventDefault();
    if (typeof e.stopPropagation === 'function') e.stopPropagation();
  }
  const menu = document.querySelector("#topbarMoreMenu");
  if (!menu) return;
  const isOpen = menu.classList.toggle("open");
  menu.style.display = isOpen ? "flex" : "none";
};

window.closeTopbarMoreMenu = function() {
  const menu = document.querySelector("#topbarMoreMenu");
  if (menu) {
    menu.classList.remove("open");
    menu.style.display = "none";
  }
};

if (typeof window !== "undefined" && !window.__moreMenuClickBound) {
  window.__moreMenuClickBound = true;
  document.addEventListener("click", (e) => {
    if (!e.target.closest("#topbarMoreContainer")) {
      const m = document.querySelector("#topbarMoreMenu");
      if (m) {
        m.classList.remove("open");
        m.style.display = "none";
      }
    }
  });
}

async function fetchBackendData() {
  try {
    const health = await api.health();
    if (health) {
      if (typeof window.updateBackendStatusBadge === 'function') {
        window.updateBackendStatusBadge(true, "SERVER ONLINE");
      }
    }
  } catch (e) {
    if (typeof window.updateBackendStatusBadge === 'function') {
      window.updateBackendStatusBadge(false, "SERVER OFFLINE");
    }
  }

  try {
    const stRes = await api.get('/api/v1/stations?limit=500');
    const items = Array.isArray(stRes) ? stRes : (stRes && stRes.items ? stRes.items : []);
    if (items.length > 0) {
      const bMap = new Map();
      items.forEach(b => {
        const c = (b.station_code || b.code || "").toUpperCase();
        if (c) bMap.set(c, b);
      });
      // Merge official stations with backend properties
      liveStations = OFFICIAL_STATIONS_37.map(stn => {
        const b = bMap.get(stn.code);
        return {
          ...stn,
          id: b ? b.id : undefined,
          status: b ? b.status : "ACTIVE"
        };
      });
      // Append any newly user-created custom stations from backend
      items.forEach(b => {
        const c = (b.station_code || b.code || "").toUpperCase();
        if (c && !OFFICIAL_STATIONS_37.some(o => o.code === c)) {
          liveStations.push({
            code: c,
            name: b.station_name || b.name || c,
            div: b.division || b.div || "MAS",
            lat: b.location && b.location.includes(',') ? parseFloat(b.location.split(',')[0]) : 11.0,
            lng: b.location && b.location.includes(',') ? parseFloat(b.location.split(',')[1]) : 77.0,
            platforms: b.platforms || 4,
            dailyTrains: 24,
            hub: false
          });
        }
      });
      window.liveStations = liveStations;
      window.OFFICIAL_STATIONS_37 = OFFICIAL_STATIONS_37;
    }
  } catch (e) { console.error('Failed to fetch stations', e); }
  
  try {
    const pRes = await api.get('/api/v1/planning/plan');
    if (pRes && pRes.items) {
       // if we have planning items, update dashboard or block planning
    }
  } catch (e) { console.error('Failed to fetch plans', e); }
}

