// ==========================================================================
// 11. MAIN RENDER ENGINE & EVENT BINDINGS
// ==========================================================================


let searchDebounce = null;
function debouncedRender() {
  clearTimeout(searchDebounce);
  searchDebounce = setTimeout(() => { render(); }, 250);
}

function render() {
  // --- OPTIMIZATION: Cleanup map and timers before re-render ---
  if (window.__trainMapTimer) clearInterval(window.__trainMapTimer);
  if (window.__dashTimer) clearInterval(window.__dashTimer);
  if (window.__weatherTimer) clearInterval(window.__weatherTimer);
  if (window.leafletMapInstance) {
    try { window.leafletMapInstance.remove(); } catch(e) {}
    window.leafletMapInstance = null;
  }
  // -------------------------------------------------------------

  const appEl = document.querySelector("#app");
  if (!appEl) return;

  if (!currentOfficial) {
    const launcher = document.querySelector("#crisCopilotLauncher");
    if (launcher) launcher.style.display = "none";
    const drawer = document.querySelector("#crisCopilotDrawer");
    if (drawer) drawer.style.display = "none";
    document.body.className = "theme-dark";
    document.documentElement.setAttribute("data-theme", "dark");
    appEl.innerHTML = renderLoginPage();
    bindLoginEvents();
    if (currentLang === "hi") {
      applyUniversalTranslation(appEl, "hi");
    }
    return;
  } else {
    document.body.className = "theme-dark";
    document.documentElement.setAttribute("data-theme", "dark");
    const launcher = document.querySelector("#crisCopilotLauncher");
    if (launcher) launcher.style.display = "flex";
  }

  document.body.classList.toggle("is-home-active", current === "Home");

  let bodyHtml = "";
  if (current === "Home") bodyHtml = renderHomePage();
  else if (current === "Dashboard") bodyHtml = renderDashboardPage();
  else if (current === "Corridor View" || current === "Corridor Map") bodyHtml = renderCorridorMapPage();
  else if (current === "Block Planning") bodyHtml = renderBlockPlanningPage();
  else if (current === "Assets" || current === "Asset Management" || current === "Asset Maintenance") bodyHtml = renderAssetMaintenancePage();
  else if (current === "Reports" || current === "Reports & Analytics") bodyHtml = renderReportsAnalyticsPage();
  else if (current === "Alerts" || current === "Defects & USFD") bodyHtml = renderDefectsUSFDPage();
  else if (current === "Block Optimization" || current === "AI Auto-Pilot") bodyHtml = renderAIAutoPilotPage();
  else if (current === "Corridors & Sections") bodyHtml = renderCorridorsSectionsPage();
  else if (current === "Stations Master") bodyHtml = renderStationsMasterPage();
  else if (current === "Station Planning") bodyHtml = renderStationPlanningPage();
  else if (current === "Block Calendar") bodyHtml = renderBlockCalendarPage();
  else if (current === "Dynamic Dispatch AI") bodyHtml = renderDynamicDispatchPage();
  else if (current === "Cost Asset Maintenance") bodyHtml = renderCostAssetMaintenancePage();
  else if (current === "Weather & Incidents") bodyHtml = renderWeatherIncidentsPage();
  else if (current === "Settings") bodyHtml = renderSettingsPage();
  else bodyHtml = renderHomePage();

  const existingShell = document.querySelector(".app-shell");
  const existingContent = document.querySelector(".main-shell > main.content");
  const navFormal = document.querySelector(".nav-formal");
  const savedNavScroll = navFormal ? navFormal.scrollTop : 0;

  if (existingShell && existingContent) {
    existingShell.classList.toggle("is-home-view", current === "Home");
    // --- SMART PARTIAL UPDATE: Retain Sidebar and Topbar; 0 Layout Shift ---
    // 1. Update active item in sidebar
    document.querySelectorAll(".sidebar .nav-item").forEach(item => {
      item.classList.toggle("active", item.dataset.nav === current);
    });

    // 1b. Update active item in topbar center action buttons and more menu items
    document.querySelectorAll(".header-center .btn-topbar-action, .more-menu-item").forEach(btn => {
      const onclickAttr = btn.getAttribute("onclick") || "";
      btn.classList.toggle("active", onclickAttr.includes(`'${current}'`) || onclickAttr.includes(`"${current}"`));
    });

    // 2. Update Topbar title
    const titleEl = document.querySelector("#topbarScreenTitle");
    if (titleEl) {
      const displayTitle = currentLang === 'hi' 
        ? (I18N.hi.nav_labels[current] || current) 
        : (current === 'Dashboard' ? 'Dashboard' : (modules[current]?.label || current));
      titleEl.textContent = displayTitle;
    }

    // 3. Swap only the main page content slot and update live countdown banner
    existingContent.outerHTML = bodyHtml;
    const authMount = document.querySelector("#dashboardAuthBannerMount");
    if (authMount) {
      authMount.innerHTML = renderDashboardAuthorizedBanner();
    }
    const countdownMount = document.querySelector("#liveCountdownMount");
    if (countdownMount) {
      countdownMount.innerHTML = renderLiveCountdownBanner();
    }

    // 4. Ensure sidebar retains exact scroll position without resetting
    if (navFormal) {
      navFormal.scrollTop = savedNavScroll;
    }
  } else {
    // --- FULL SHELL MOUNT ---
    appEl.innerHTML = `
      ${renderGovTopStrip()}
      <div class="app-shell ${current === 'Home' ? 'is-home-view' : ''}">
        ${renderSidebar()}
        <div class="main-shell">
          ${renderTopbar()}
          ${bodyHtml}
        </div>
      </div>
    `;
    // Clean up any residual RailBlock Copilot elements from previous sessions
    const oldCopilot = document.querySelector("#railblockCopilotDrawer");
    if (oldCopilot) oldCopilot.remove();
    const oldFab = document.querySelector("#btnOpenCopilot");
    if (oldFab) oldFab.remove();

    const newNav = document.querySelector(".nav-formal");
    if (newNav && savedNavScroll > 0) {
      newNav.scrollTop = savedNavScroll;
    }
  }

  if (!window.__api_fetched) {
    window.__api_fetched = true;
    if (typeof window.checkBackendHealth === 'function') {
      window.checkBackendHealth(true);
    }
    fetchBackendData().then(() => render());
    if (!window.__healthInterval) {
      window.__healthInterval = setInterval(() => {
        if (typeof window.checkBackendHealth === 'function') {
          window.checkBackendHealth(true);
        }
      }, 10000);
    }
  }

  bindEvents();
  tick();

  if (!window.__clock) {
    window.__clock = setInterval(tick, 1000);
  }

  if (current === "Dashboard") {
    loadDashboardMetrics();
    initHighResMap();
  } else if (current === "Block Optimization" || current === "AI Auto-Pilot") {
    initAIAutoPilotPage();
  } else if (current === "Corridor Map") {
    initCorridorMap();
  } else if (current === "GIS Network") {
    initGISCartographyMap();
  } else if (current === "Live Train GPS") {
    initLiveTrainGPSMap();
  } else if (current === "Maintenance") {
    initMaintenanceMachineryMap();
  } else if (current === "Defects & USFD") {
    initDefectsUSFDPage();
  } else if (current === "Weather & Incidents") {
    initWeatherIncidentsPage(false);
  }

  if (typeof window.mountCopilotDOM === "function") {
    window.mountCopilotDOM();
  }

  if (currentLang === "hi") {
    applyUniversalTranslation(appEl, "hi");
  }
}

